#include <stdio.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <pthread.h>

typedef struct Node {
    int value;
    _Atomic(struct Node*) next;
} Node;

typedef struct Queue {
    _Atomic(Node*) head;
    _Atomic(Node*) tail;
} Queue;

Queue q;

void init_queue(Queue* queue) {
    Node* dummy = malloc(sizeof(Node));
    dummy->value = 0;
    atomic_init(&dummy->next, NULL);
    atomic_init(&queue->head, dummy);
    atomic_init(&queue->tail, dummy);
}

void enqueue(Queue* queue, int value) {
    Node* node = malloc(sizeof(Node));
    if (!node) exit(1);
    node->value = value;
    atomic_init(&node->next, NULL);
    while (1) {
        Node* tail = atomic_load(&queue->tail);
        Node* next = atomic_load(&tail->next);
        if (tail == atomic_load(&queue->tail)) {
            if (next == NULL) {
                if (atomic_compare_exchange_weak(&tail->next, &next, node)) {
                    atomic_compare_exchange_weak(&queue->tail, &tail, node);
                    break;
                }
            } else {
                atomic_compare_exchange_weak(&queue->tail, &tail, next);
            }
        }
    }
}

int dequeue(Queue* queue, int* value) {
    while (1) {
        Node* head = atomic_load(&queue->head);
        Node* tail = atomic_load(&queue->tail);
        Node* next = atomic_load(&head->next);
        if (head == atomic_load(&queue->head)) {
            if (head == tail) {
                if (next == NULL) {
                    return 0; /* Empty */
                }
                atomic_compare_exchange_weak(&queue->tail, &tail, next);
            } else {
                if (next == NULL) continue;
                *value = next->value;
                if (atomic_compare_exchange_weak(&queue->head, &head, next)) {
                    break;
                }
            }
        }
    }
    return 1;
}

void* worker(void* arg) {
    (void)arg;
    for (int i = 0; i < 10000; i++) {
        enqueue(&q, i);
    }
    int val;
    for (int i = 0; i < 10000; i++) {
        while (!dequeue(&q, &val)) {}
    }
    return NULL;
}

int main(void) {
    init_queue(&q);
    pthread_t threads[16];
    for (int i = 0; i < 16; i++) {
        if (pthread_create(&threads[i], NULL, worker, NULL) != 0) {
            perror("Failed to create thread");
            exit(1);
        }
    }
    for (int i = 0; i < 16; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("FLAG: Queue Success!\n");
    return 0;
}
